  const code = err && (err.code || (err.cause && err.cause.code));
  return ['ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN', 'ECONNRESET', 'ETIMEDOUT', 'ECONNABORTED'].includes(code)
    || /timeout|ECONNREFUSED|ENOTFOUND|EAI_AGAIN/i.test(String(err && err.message));
}
function safeError(node, status) {
