const NODE = 'memory.write';
const body = $input.first().json.body ?? {};
const trace_id = String(body.trace_id ?? 'no-trace-id').slice(0, 64);
const payload = (body.event && typeof body.event.payload === 'object' && body.event.payload) || {};
// Configured agent only; a caller-supplied agent_id must be well-formed AND equal to it.
const AGENT_ID = 'agent-9972f1c0-0dd2-4ebc-be75-fba370d1f70b';
const ID_RE = /^[A-Za-z0-9_-]+$/;
const BLOCKS = ['human', 'persona'];
function bad(msg) { return [{ json: { valid: false, ok: false, trace_id, error: { message: msg, node: NODE } } }]; }
if (payload.agent_id !== undefined) {
  if (typeof payload.agent_id !== 'string' || !ID_RE.test(payload.agent_id)) return bad('invalid agent_id');
  if (payload.agent_id !== AGENT_ID) return bad('agent_id not allowed');
}
const content = payload.content;
const mode = payload.mode ?? 'append';
const block = payload.block ?? 'human';
if (typeof content !== 'string' || !content.length) return bad('content must be a non-empty string');
if (content.length > 8000) return bad('content exceeds 8000 characters');
if (!['append', 'replace'].includes(mode)) return bad('mode must be append or replace');
if (typeof block !== 'string' || !ID_RE.test(block) || !BLOCKS.includes(block)) return bad('invalid block');
const base = 'http://letta:8283/v1/agents/' + encodeURIComponent(AGENT_ID) + '/core-memory';
return [{ json: { valid: true, trace_id, content, mode, block, get_url: base, patch_url: base + '/blocks/' + encodeURIComponent(block) } }];

const prep = $('MW Prepare').first().json;
const res = $input.first().json;
if (!(res.statusCode >= 200 && res.statusCode < 300)) {
  return [{ json: { proceed: false, ok: false, trace_id: prep.trace_id, error: { message: 'memory.write failed', node: 'memory.write', status: res.statusCode ?? null } } }];
}
let value = prep.content;
if (prep.mode === 'append') {
  const blocks = (res.body && res.body.blocks) || [];
  const t = blocks.find((b) => b.label === prep.block);
  value = (t ? t.value : '') + '\n' + prep.content;
}
// Letta blocks reject values over 20000 chars: keep the newest entries under 15000,
// dropping the oldest lines first (a single oversized entry keeps its newest tail).
const MAX_CHARS = 15000;
let trimmed = 0;
if (value.length > MAX_CHARS) {
  const lines = value.split('\n');
  while (lines.length > 1 && lines.join('\n').length > MAX_CHARS) { lines.shift(); trimmed++; }
  value = lines.join('\n');
  if (value.length > MAX_CHARS) { value = value.slice(-MAX_CHARS); trimmed++; }
}
return [{ json: { proceed: true, trace_id: prep.trace_id, patch_url: prep.patch_url, value, trimmed } }];

