// Crew key check. The webhook has no n8n auth because n8n's Header Auth compares with !== and
// answers 403; here a missing or wrong key is 401 and the compare is constant-time.
// EXPECTED is the SHA-256 hex of CREW_INGRESS_SECRET, filled in at import time by
// stack/scripts/n8n_render_crew_auth.sh. Left as the placeholder it never matches (fail closed).
// The header is hashed and dropped here: no later node, response or log sees it.
const EXPECTED = '__CREW_KEY_SHA256__';
function sha256hex(s) {
