  for (let n = 2; P.length < 64; n++) if (P.every((q) => n % q)) P.push(n);
  const frac = (x) => ((x - Math.floor(x)) * 0x100000000) | 0;
  const K = P.map((q) => frac(Math.cbrt(q)));
  let H = P.slice(0, 8).map((q) => frac(Math.sqrt(q)));
  const b = [];
  for (let i = 0; i < s.length; i++) b.push(s.charCodeAt(i));
  const bits = b.length * 8;
  b.push(0x80);
  while (b.length % 64 !== 56) b.push(0);
  for (let i = 7; i >= 0; i--) b.push(i >= 4 ? 0 : (bits >>> (i * 8)) & 0xff);
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let o = 0; o < b.length; o += 64) {
    for (let i = 0; i < 16; i++) w[i] = (b[o + 4 * i] << 24) | (b[o + 4 * i + 1] << 16) | (b[o + 4 * i + 2] << 8) | b[o + 4 * i + 3];
    for (let i = 16; i < 64; i++) {
      const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [A, B, C, D, E, F, G, X] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (X + (r(E, 6) ^ r(E, 11) ^ r(E, 25)) + ((E & F) ^ (~E & G)) + K[i] + w[i]) | 0;
      const t2 = ((r(A, 2) ^ r(A, 13) ^ r(A, 22)) + ((A & B) ^ (A & C) ^ (B & C))) | 0;
      X = G; G = F; F = E; E = (D + t1) | 0; D = C; C = B; B = A; A = (t1 + t2) | 0;
    }
    H = [A, B, C, D, E, F, G, X].map((v, i) => (v + H[i]) | 0);
  }
  return H.map((v) => (v >>> 0).toString(16).padStart(8, '0')).join('');
}
function safeEqual(a, b) {
  // Fixed 64 iterations whatever the inputs; the length difference is folded in.
  let diff = a.length ^ b.length;
  for (let i = 0; i < 64; i++) diff |= (a.charCodeAt(i) | 0) ^ (b.charCodeAt(i) | 0);
  return diff === 0;
}
const item = $input.first().json;
const headers = item.headers || {};
const got = typeof headers['x-nexus-secret'] === 'string' ? headers['x-nexus-secret'] : '';
const authorized = /^[0-9a-f]{64}$/.test(EXPECTED) && /^[\x21-\x7e]{1,512}$/.test(got)
